    public async Task<JsonObject> Templates(string id,string? identifier,CancellationToken cancellation){var c=Get(id);if(identifier is not null&&(!Regex.IsMatch(identifier,"^[A-Za-z0-9_ .:-]{1,300}$")||identifier.Contains("..",StringComparison.Ordinal)))throw new ProcessingException("CDR_TEMPLATE_IDENTIFIER_INVALID");return await Request(c,S(c,"apiUrl").TrimEnd('/')+"/definition/template/adl1.4"+(identifier is null?"":"/"+Uri.EscapeDataString(identifier)),HttpMethod.Get,null,cancellation,true,identifier);}
